/**
 * Which 3D model to draw for an aircraft: ICAO type designator → model, falling back to the model class.
 * The manifest is generated by `npm run data:models` and extended by `npm run models:import` (licensed models).
 */
import type { ModelClass } from './aircraftTypes';
import manifestJson from './aircraftModels.json';

export interface ModelEntry {
  /** Path under /models/. */
  file: string;
  /** Content hash, appended as ?v= so the files can be cached as immutable. */
  rev?: string;
  name: string;
  cls: ModelClass;
  /** Real dimensions, m. */
  length: number;
  span: number;
  height: number;
  /** Has the `_LIVERY` vertex attribute (tail/winglets painted in the operator's colour). */
  livery: boolean;
  /** Has a retractable "gear" node. */
  gear: boolean;
  source: 'generated' | 'licensed';
  licence?: string;
  author?: string;
  url?: string;
}

export interface ModelManifest {
  v: 1;
  models: Record<string, ModelEntry>;
  types: Record<string, string>;
  classes: Record<ModelClass, string>;
}

const manifest = manifestJson as unknown as ModelManifest;

export function modelIdFor(type: string | undefined, cls: ModelClass): string {
  const t = type?.toUpperCase();
  const id = (t && manifest.types[t]) || manifest.classes[cls] || manifest.classes.generic;
  return manifest.models[id] ? id : manifest.classes.generic;
}

export function modelEntry(id: string): ModelEntry {
  return manifest.models[id] ?? manifest.models[manifest.classes.generic];
}

/** URL of a model file (versioned by content hash). */
export function modelUrl(e: ModelEntry): string {
  return `/models/${e.file}${e.rev ? `?v=${e.rev}` : ''}`;
}

export function allModels(): Readonly<Record<string, ModelEntry>> {
  return manifest.models;
}
